import portraitsJson from './bilder.json';
import creditsJson from './credits.json';
import type { WorkView } from '../kunst/works';

// Pictures shown in Politik (politicians, buildings, documents, events): bilder.json (hand-written) + credits.json
// (generated by scripts/fetch-bilder.mjs politik: author and licence from Wikimedia Commons).
interface Portrait { wiki: string; title: string; artist: string; year: string; file?: string }
interface Credit { file: string; author: string; licence: string; licenceUrl?: string; page: string }

const PORTRAITS = portraitsJson as Record<string, Portrait>;
const CREDITS = creditsJson as Record<string, Credit>;

export const hasPolBild = (key: string) => key in PORTRAITS && key in CREDITS;
export const polBildKeys = () => Object.keys(PORTRAITS);

export function polView(key: string): WorkView | null {
  const p = PORTRAITS[key];
  const c = CREDITS[key];
  if (!p || !c) return null;
  const author = c.author === 'unbekannt' ? '' : `${c.author}, `;
  return {
    key,
    src: `/politik/${key}.jpg`,
    title: p.title,
    artist: p.artist,
    year: p.year,
    credit: c.licence.toLowerCase().startsWith('public domain') ? 'Gemeinfrei · Wikimedia Commons' : `Bild: ${author}${c.licence} · Wikimedia Commons`,
    page: c.page,
  };
}
